export * from './math/interpolate';
export * from './math/intervals';
export * from './math/spline';

export interface LivelinePoint {
	time: number; // unix seconds
	value: number;
}

export type Momentum = 'up' | 'down' | 'flat';
export type ThemeMode = 'light' | 'dark';
export type WindowStyle = 'default' | 'rounded' | 'text';
export type BadgeVariant = 'default' | 'minimal';

export interface ReferenceLine {
	value: number;
	label?: string;
}

export interface HoverPoint {
	time: number;
	value: number;
	x: number;
	y: number;
}

export interface Padding {
	top?: number;
	right?: number;
	bottom?: number;
	left?: number;
}

export interface WindowOption {
	label: string;
	secs: number;
}

export interface OrderbookData {
	bids: [number, number][]; // [price, size][]
	asks: [number, number][]; // [price, size][]
}

export interface DegenOptions {
	/** Multiplier for particle count and size (default 1) */
	scale?: number;
	/** Show particles on down-momentum swings (default false) */
	downMomentum?: boolean;
}

export interface LivelineSeries {
	id: string;
	data: LivelinePoint[];
	value: number;
	color: string;
	label?: string;
}

export interface LivelineOptions {
	data: LivelinePoint[];
	value: number;

	// Multi-series mode — when provided, overrides data/value/color
	series?: LivelineSeries[];

	// Appearance
	/** Explicit modes always win. When omitted, inherits --tile-color-mode if provided by a theme stylesheet; otherwise defaults to dark. */
	theme?: ThemeMode;
	color?: string;

	// Time
	window?: number;

	// Feature flags
	grid?: boolean;
	badge?: boolean;
	momentum?: boolean | Momentum;
	fill?: boolean;
	loading?: boolean; // Show loading animation — breathing line (default: false)
	paused?: boolean; // Pause chart scrolling (default: false)
	emptyText?: string; // Text shown in the empty state (default: 'No data to display')
	scrub?: boolean; // Enable crosshair scrubbing on hover (default: true)
	exaggerate?: boolean; // Tight Y-axis range — small moves fill chart height (default: false)
	showValue?: boolean; // Show live value as DOM text overlay (default: false)
	valueMomentumColor?: boolean; // Color the value text by momentum — green/red (default: false)
	degen?: boolean | DegenOptions; // Degen mode — burst particles + chart shake on momentum swings (default: false)
	badgeTail?: boolean; // Show pointed tail on badge pill (default: true)

	// Time window buttons
	windows?: WindowOption[];
	onWindowChange?: (secs: number) => void;
	windowStyle?: WindowStyle;

	// Badge
	badgeVariant?: BadgeVariant; // Badge visual style: 'default' (accent) or 'minimal' (white + grey text)

	// Crosshair
	tooltipY?: number; // Vertical offset for crosshair tooltip text (default: 14)
	tooltipOutline?: boolean; // Stroke outline around crosshair tooltip text for readability (default: true)

	// Orderbook
	orderbook?: OrderbookData;

	// Optional
	referenceLine?: ReferenceLine;
	formatValue?: (v: number) => string;
	formatTime?: (t: number) => string;
	lerpSpeed?: number;
	padding?: Padding;
	onHover?: (point: HoverPoint | null) => void;
	cursor?: string; // CSS cursor on hover (default: 'crosshair')
	pulse?: boolean; // Pulsing ring on live dot (default: true)
	lineWidth?: number; // Stroke width of the main line in px (default: 2)

	// Candlestick mode
	mode?: 'line' | 'candle'; // Chart type (default: 'line')
	candles?: CandlePoint[]; // OHLC candle data (required when mode='candle')
	candleWidth?: number; // Seconds per candle (required when mode='candle')
	liveCandle?: CandlePoint; // Current live candle with real-time OHLC
	lineMode?: boolean; // Morph candles into line display
	lineData?: LivelinePoint[]; // Tick-level data for density transition
	lineValue?: number; // Current tick value for density transition
	onModeChange?: (mode: 'line' | 'candle') => void; // Built-in toggle callback
	onSeriesToggle?: (id: string, visible: boolean) => void; // Multi-series toggle callback
	seriesToggleCompact?: boolean; // Show only colored dots (no labels) in series toggle (default: false)
}

/** Framework adapters may extend this with their own host styling props. */
export type LivelineProps = LivelineOptions;

export interface CandlePoint {
	time: number; // unix seconds — candle open time
	open: number;
	high: number;
	low: number;
	close: number;
}

export interface LivelinePalette {
	// Line
	line: string;
	lineWidth: number;

	// Fill gradient
	fillTop: string;
	fillBottom: string;

	// Grid
	gridLine: string;
	gridLabel: string;

	// Dot
	dotUp: string;
	dotDown: string;
	dotFlat: string;
	glowUp: string;
	glowDown: string;
	glowFlat: string;

	// Badge
	badgeOuterBg: string;
	badgeOuterShadow: string;
	badgeBg: string;
	badgeText: string;

	// Dash line
	dashLine: string;

	// Reference line
	refLine: string;
	refLabel: string;

	// Time axis
	timeLabel: string;

	// Crosshair
	crosshairLine: string;
	tooltipBg: string;
	tooltipText: string;
	tooltipBorder: string;

	// Background (for color fading — labels fade toward bg instead of alpha)
	bgRgb: [number, number, number];

	// Fonts
	labelFont: string;
	valueFont: string;
	badgeFont: string;
}

export interface ChartLayout {
	w: number;
	h: number;
	pad: Required<Padding>;
	chartW: number;
	chartH: number;
	leftEdge: number;
	rightEdge: number;
	minVal: number;
	maxVal: number;
	valRange: number;
	toX: (t: number) => number;
	toY: (v: number) => number;
}

import type { ThemeMode, LivelinePalette, LivelineSeries } from './types';

/** Parse concrete hex/rgb colors. Resolve CSS variables and modern color spaces at the browser boundary first. */
export function parseColorRgb(color: string): [number, number, number] {
	const hex = color.trim().match(/^#([0-9a-f]{3}|[0-9a-f]{4}|[0-9a-f]{6}|[0-9a-f]{8})$/i);
	if (hex) {
		let h = hex[1];
		if (h.length <= 4) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
		return [parseInt(h.slice(0, 2), 16), parseInt(h.slice(2, 4), 16), parseInt(h.slice(4, 6), 16)];
	}
	const rgb = color.trim().match(/^rgba?\(\s*([\d.+-]+%?)[,\s]+([\d.+-]+%?)[,\s]+([\d.+-]+%?)(?:\s*[,/]\s*[\d.+-]+%?)?\s*\)$/i);
	if (rgb)
		return rgb.slice(1, 4).map((channel) => Math.round(Math.max(0, Math.min(255, channel.endsWith('%') ? (parseFloat(channel) / 100) * 255 : parseFloat(channel))))) as [
			number,
			number,
			number,
		];
	return [128, 128, 128];
}

function rgba(r: number, g: number, b: number, a: number): string {
	return `rgba(${r}, ${g}, ${b}, ${a})`;
}

/**
 * Derive a full palette from a single accent color + theme mode.
 * Momentum colors are always semantic green/red regardless of accent.
 */
export function resolveTheme(color: string, mode: ThemeMode): LivelinePalette {
	const [r, g, b] = parseColorRgb(color);
	const isDark = mode === 'dark';

	return {
		// Line
		line: color,
		lineWidth: 2,

		// Fill gradient
		fillTop: rgba(r, g, b, isDark ? 0.12 : 0.08),
		fillBottom: rgba(r, g, b, 0),

		// Grid
		gridLine: isDark ? 'rgba(255, 255, 255, 0.06)' : 'rgba(0, 0, 0, 0.06)',
		gridLabel: isDark ? 'rgba(255, 255, 255, 0.4)' : 'rgba(0, 0, 0, 0.35)',

		// Dot — always semantic
		dotUp: '#22c55e',
		dotDown: '#ef4444',
		dotFlat: color,
		glowUp: 'rgba(34, 197, 94, 0.18)',
		glowDown: 'rgba(239, 68, 68, 0.18)',
		glowFlat: rgba(r, g, b, 0.12),

		// Badge
		badgeOuterBg: isDark ? 'rgba(40, 40, 40, 0.95)' : 'rgba(255, 255, 255, 0.95)',
		badgeOuterShadow: isDark ? 'rgba(0, 0, 0, 0.4)' : 'rgba(0, 0, 0, 0.15)',
		badgeBg: color,
		badgeText: '#ffffff',

		// Dash line
		dashLine: rgba(r, g, b, 0.4),

		// Reference line
		refLine: isDark ? 'rgba(255, 255, 255, 0.15)' : 'rgba(0, 0, 0, 0.12)',
		refLabel: isDark ? 'rgba(255, 255, 255, 0.45)' : 'rgba(0, 0, 0, 0.4)',

		// Time axis
		timeLabel: isDark ? 'rgba(255, 255, 255, 0.35)' : 'rgba(0, 0, 0, 0.3)',

		// Crosshair
		crosshairLine: isDark ? 'rgba(255, 255, 255, 0.2)' : 'rgba(0, 0, 0, 0.12)',
		tooltipBg: isDark ? 'rgba(30, 30, 30, 0.95)' : 'rgba(255, 255, 255, 0.95)',
		tooltipText: isDark ? '#e5e5e5' : '#1a1a1a',
		tooltipBorder: isDark ? 'rgba(255, 255, 255, 0.1)' : 'rgba(0, 0, 0, 0.08)',

		// Background
		bgRgb: isDark ? ([10, 10, 10] as [number, number, number]) : ([255, 255, 255] as [number, number, number]),

		// Fonts
		labelFont: '11px "SF Mono", Menlo, Monaco, "Cascadia Code", monospace',
		valueFont: '600 11px "SF Mono", Menlo, monospace',
		badgeFont: '500 11px "SF Mono", Menlo, monospace',
	};
}

/** Default color palette for multi-series when no colors specified. */
export const SERIES_COLORS = [
	'#3b82f6', // blue
	'#ef4444', // red
	'#22c55e', // green
	'#f59e0b', // amber
	'#8b5cf6', // violet
	'#ec4899', // pink
	'#06b6d4', // cyan
	'#f97316', // orange
];

/** Derive per-series palettes from series definitions. */
export function resolveSeriesPalettes(series: LivelineSeries[], mode: ThemeMode): Map<string, LivelinePalette> {
	const map = new Map<string, LivelinePalette>();
	for (let i = 0; i < series.length; i++) {
		const s = series[i];
		const color = s.color || SERIES_COLORS[i % SERIES_COLORS.length];
		map.set(s.id, resolveTheme(color, mode));
	}
	return map;
}

import { parseColorRgb, resolveTheme } from './theme';
import type { LivelinePalette, ThemeMode } from './types';

/** A browser-resolved snapshot; safe to consume from pure palette functions/render code. */
export interface LivelineAppearance {
	mode: ThemeMode;
	/** Do not emit a data-theme boundary when inheriting the stylesheet's mode. */
	inherited?: boolean;
	palette: Partial<LivelinePalette>;
	colors: Record<string, string>;
}

function colorMode(value: string): ThemeMode | undefined {
	const mode = value.trim();
	return mode === 'light' || mode === 'dark' ? mode : undefined;
}

function concreteColor(color: string): boolean {
	return /^#(?:[0-9a-f]{3,4}|[0-9a-f]{6}|[0-9a-f]{8})$/i.test(color.trim()) || /^rgba?\([\d\s.,%+\-/]+\)$/i.test(color.trim());
}

/** Resolve the browser's supported CSS colors to sRGB before any canvas color math. */
function colorResolver(element: HTMLElement): { resolve: (color: string) => string | undefined; destroy: () => void } {
	const document = element.ownerDocument;
	const view = document.defaultView!;
	const probe = document.createElement('span');
	probe.setAttribute('aria-hidden', 'true');
	probe.style.cssText = 'position:absolute;visibility:hidden;pointer-events:none;width:0;height:0;overflow:hidden';
	element.appendChild(probe);
	let context: CanvasRenderingContext2D | null | undefined;
	const cache = new Map<string, string | undefined>();
	return {
		resolve(color) {
			if (cache.has(color)) return cache.get(color);
			// Avoid changing legacy accents (and avoid browser work for their gradients).
			if (concreteColor(color)) return color;
			probe.style.color = '';
			probe.style.color = color;
			if (!probe.style.color) return undefined;
			const computed = view.getComputedStyle(probe).color;
			let resolved: string | undefined;
			if (concreteColor(computed)) {
				const [r, g, b] = parseColorRgb(computed);
				const alpha = computed.match(/[,/]\s*([\d.]+%?)\s*\)$/)?.[1];
				// Only rgba/comma-fourth-channel and slash syntax contain an alpha channel.
				const hasAlpha = computed.includes('/') || computed.split(',').length === 4;
				const a = hasAlpha && alpha ? parseFloat(alpha) / (alpha.endsWith('%') ? 100 : 1) : 1;
				resolved = `rgba(${r}, ${g}, ${b}, ${a})`;
			} else if (computed && !computed.includes('var(')) {
				// getComputedStyle may retain oklch()/color()/color-mix(). Rasterization
				// converts those supported browser colors to concrete, clipped sRGB.
				try {
					if (context === undefined) {
						const canvas = document.createElement('canvas');
						canvas.width = canvas.height = 1;
						context = canvas.getContext('2d', { willReadFrequently: true });
					}
					if (context) {
						context.clearRect(0, 0, 1, 1);
						context.fillStyle = computed;
						context.fillRect(0, 0, 1, 1);
						const [r, g, b, a] = context.getImageData(0, 0, 1, 1).data;
						resolved = `rgba(${r}, ${g}, ${b}, ${a / 255})`;
					}
				} catch {
					// Non-browser renderers may not implement canvas; retain legacy colors.
				}
			}
			cache.set(color, resolved);
			return resolved;
		},
		destroy: () => probe.remove(),
	};
}

/**
 * Browser boundary for the generic --tile-color-mode contract. Omitted themes read
 * the parent so the adapter's own resolved data-theme does not lock inheritance.
 * Explicit themes never inherit a conflicting parent's semantic palette.
 */
export function readLivelineAppearance(element?: HTMLElement | null, theme?: ThemeMode, colors: readonly string[] = []): LivelineAppearance {
	const fallback: LivelineAppearance = { mode: theme ?? 'dark', palette: {}, colors: {} };
	const view = element?.ownerDocument.defaultView;
	if (!element || !view) return fallback;
	const computed = view.getComputedStyle(element);
	const inheritedMode = element.parentElement ? colorMode(view.getComputedStyle(element.parentElement).getPropertyValue('--tile-color-mode')) : undefined;
	const mode = theme ?? inheritedMode ?? 'dark';
	const themed = colorMode(computed.getPropertyValue('--tile-color-mode')) === mode;
	const resolver = colorResolver(element);
	try {
		const resolvedColors: Record<string, string> = {};
		for (const color of colors) {
			const resolved = resolver.resolve(color);
			if (resolved) resolvedColors[color] = resolved;
		}
		const palette: Partial<LivelinePalette> = {};
		if (themed) {
			const semantic = (...names: string[]) => {
				const value = names.map((name) => computed.getPropertyValue(name).trim()).find(Boolean);
				return value ? resolver.resolve(value) : undefined;
			};
			const background = semantic('--tile-liveline-background', '--background');
			const foreground = semantic('--tile-liveline-foreground', '--foreground');
			const muted = semantic('--tile-liveline-muted-foreground', '--muted-foreground');
			const border = semantic('--tile-liveline-border', '--border');
			const surface = semantic('--tile-liveline-tooltip-background', '--popover', '--background');
			const text = semantic('--tile-liveline-tooltip-foreground', '--popover-foreground', '--foreground');
			if (background) palette.bgRgb = parseColorRgb(background);
			if (foreground) palette.tooltipText = foreground;
			if (muted) palette.gridLabel = palette.refLabel = palette.timeLabel = muted;
			if (border) palette.gridLine = palette.refLine = palette.crosshairLine = palette.tooltipBorder = border;
			if (surface) palette.tooltipBg = palette.badgeOuterBg = surface;
			if (text) palette.tooltipText = text;
		}
		return { mode, inherited: !theme && Boolean(inheritedMode), palette, colors: resolvedColors };
	} finally {
		resolver.destroy();
	}
}

/** Pure palette construction from a browser snapshot (or the legacy SSR default). */
export function resolveLivelinePalette(color: string, appearance: LivelineAppearance): LivelinePalette {
	// Unsupported browser colors must not quietly become parseColorRgb's gray.
	const resolved = appearance.colors[color] ?? (concreteColor(color) ? color : '#3b82f6');
	return { ...resolveTheme(resolved, appearance.mode), ...appearance.palette };
}

/** Observe only theme-bearing ancestors, never canvas/value DOM mutations. */
export function observeLivelineAppearance(
	element: HTMLElement,
	read: () => { theme?: ThemeMode; colors: readonly string[] },
	onChange: (appearance: LivelineAppearance) => void,
): () => void {
	const view = element.ownerDocument.defaultView;
	let previous = '';
	const update = () => {
		const { theme, colors } = read();
		const appearance = readLivelineAppearance(element, theme, colors);
		const next = JSON.stringify(appearance);
		if (next !== previous) {
			previous = next;
			onChange(appearance);
		}
	};
	const observer = view?.MutationObserver ? new view.MutationObserver(update) : undefined;
	for (let ancestor: HTMLElement | null = element; ancestor; ancestor = ancestor.parentElement) {
		observer?.observe(ancestor, { attributes: true, attributeFilter: ['class', 'data-theme', 'style'] });
	}
	// Covers a stylesheet loaded after mounting without observing unrelated DOM updates.
	view?.addEventListener('load', update, true);
	update();
	return () => {
		observer?.disconnect();
		view?.removeEventListener('load', update, true);
	};
}

