	scrub: boolean;
	exaggerate: boolean;
	degenOptions?: DegenOptions;
	badgeTail: boolean;
	badgeVariant: BadgeVariant;
	tooltipY: number;
	tooltipOutline: boolean;
	valueMomentumColor: boolean;
