}

export interface LivelineEngineEnvironment {
	document?: Document;
	now?: () => number;
	performanceNow?: () => number;
	requestAnimationFrame?: (callback: FrameRequestCallback) => number;
	cancelAnimationFrame?: (handle: number) => void;
	ResizeObserver?: typeof ResizeObserver;
